// === プロパティ定義と初期化 ===
var m = properties["Ratio"]; // m (分割比率) は0~1
var p = properties["Power"]; // p (パワー)
var s = properties["Sync"]; // Sync値
var amount_eased = properties["Amount"][0]; // イージングして増加する量
var amount_linear = properties["Amount"][1]; // 一次関数的に加算される量

// === 1. Syncを整数部と小数部に分解 ===
var I = (s >= 0) ? (s - s % 1) : (s - s % 1 - (s % 1 != 0 ? 1 : 0));
var s_frac = s - I;

// === 2. ゼロ除算回避の分母設定 ===
var EPSILON = 0.000001; 

// m_safe: Outイージングの分母
var m_is_zero = (m < EPSILON) ? 1 : 0;
var m_safe = m * (1 - m_is_zero) + EPSILON * m_is_zero; 

// m1_safe: Inイージングの分母
var m1 = 1 - m;
var m1_is_zero = (m1 < EPSILON) ? 1 : 0;
var m1_safe = m1 * (1 - m1_is_zero) + EPSILON * m1_is_zero; 

// === 3. Easing Shape の計算 ===

// --- Outイージング (0 <= s_frac < m) ---
var x1 = s_frac / m_safe;
var v1 = (1 - pow(1 - x1, p)) * 0.5;

// --- Inイージング (m <= s_frac < 1) ---
var x2 = (s_frac - m) / m1_safe;
var v2 = 0.5 + pow(x2, p) * 0.5;

// 区間フラグ
var flag1 = (s_frac < m) ? 1 : 0;
var flag2 = (s_frac >= m) ? 1 : 0;

// E_shape (0から1へ Out-In イージングで変化)
var E_shape = v1 * flag1 + v2 * flag2;

// === 4. 最終結果の計算 ===
// イージング成分: (整数部 + イージング小数部) × amount_eased
// リニア成分: Sync × amount_linear
(I + E_shape) * amount_eased + s * amount_linear;

